fn toggle_case(s: Vec<char>) -> Vec<char> {
    s.into_iter()
     .map(|c| match c {
         'a'..='z' => ((c as u8 - 32) as char),
         'A'..='Z' => ((c as u8 + 32) as char),
         _ => c,
     })
     .collect()
}

